import{_ as t,o as a,c as s,a2 as o}from"./chunks/framework.DDa4BI30.js";const m=JSON.parse('{"title":"1D Transport","description":"","frontmatter":{},"headers":[],"relativePath":"guide/one-d.md","filePath":"guide/one-d.md"}'),n={name:"guide/one-d.md"};function i(r,e,d,c,h,p){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="_1d-transport" tabindex="-1">1D Transport <a class="header-anchor" href="#_1d-transport" aria-label="Permalink to &quot;1D Transport&quot;">​</a></h1><p>On a line, transport needs no Newton loop. The monotone map is optimal: sort the diracs, accumulate their masses, and invert the cumulative distribution function of the density at those masses. sdot uses this whenever the problem is 1D:</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">plan </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> sdot.ot_solve( sdot.SumOfDiracs( x[ :, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">None</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ] ), sdot.Image( </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">values</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> density ) )   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># d = 1: a `SdotPlan1d`, exact</span></span></code></pre></div><p>In 1D, <code>ot_solve</code> returns a <code>SdotPlan1d</code>, whose settings are a <code>Direct</code>: the result is exact, and the cost, the barycenters and the gradients with respect to the positions come from a single pass. The image may have constant pixels or affine ones ( <code>Image( values = coeffs, degree = 1 )</code>, <code>coeffs [ pixels, 2 ]</code> the density at both ends of each pixel: a piecewise linear density ); the gradients then go to its coefficients.</p><p>Between two images, <code>ContinuousOtPlan1d( Image, Image )</code> needs no sort: it merges the pixels of both ( degree 0 or 1 on each side ), O( pixels ). It computes the cost only.</p><h2 id="many-transports-at-once" tabindex="-1">Many transports at once <a class="header-anchor" href="#many-transports-at-once" aria-label="Permalink to &quot;Many transports at once&quot;">​</a></h2><p>The 1D case matters most when there are many transports between the projections of the same objects, for example the projections of a cloud along hundreds of directions in tomography or in sliced transport. The plans take a batch of directions. The projected source is never stored: with 1e7 points and 600 directions, the <code>[ directions, n ]</code> array of projected positions would be 48 GB. The kernels compute the projections on the fly and send the gradients back to the shared points ( <a href="./distributions/projected.html">Projected Sources</a> ):</p><table tabindex="0"><thead><tr><th>Plan</th><th>source</th><th></th></tr></thead><tbody><tr><td><code>SdotPlan1d( ProjectedSumOfDiracs, Image )</code></td><td>diracs</td><td>exact, by a sort per direction</td></tr><tr><td><code>ContinuousOtPlan1d( ProjectedSumOfTents, Image )</code></td><td>tents ( a half-width per point )</td><td>exact: the breakpoints sorted, the map quadratic on each piece</td></tr><tr><td><code>ContinuousOtPlan1d( ..., method = &quot;grid&quot;, scale = 8 )</code></td><td>tents</td><td>the tents deposited on a fine grid, no sort: <code>O( directions × cells )</code></td></tr><tr><td><code>projected1d.ProjectedLoss1d</code></td><td>domes or tents</td><td>the same grid transport, value and gradient in one call</td></tr></tbody></table><h2 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to &quot;Performance&quot;">​</a></h2><p>The timings, against POT and scipy, are on <a href="./performance-1d.html">Performance: 1D Transport</a>.</p>',10)])])}const u=t(n,[["render",i]]);export{m as __pageData,u as default};
